        overviewWelcome: 'வரவேற்கிறோம், {{name}}!',
        overviewIntro: 'அடுத்து என்ன செய்ய வேண்டும் என்பதைத் தேர்வு செய்யுங்கள். ஆதரவைத் தேடலாம், பயனுள்ள வளங்களைச் சேமிக்கலாம், அல்லது சுயவிவரத்தைப் புதுப்பிக்கலாம்.',
