        dashboardOpsEnglishBody: 'வள மேலாண்மை மற்றும் நிர்வாகப் பக்கங்களில் துல்லியமான செயல்பாட்டு சொற்கள், இறக்குமதி முறைகள், அனுமதி பெயர்கள் உள்ளன. பயனர் பார்க்கும் பக்கங்கள் மொழிபெயர்க்கப்படுகின்றன; இந்த ஆழமான கருவிகள் துல்லியத்திற்காக ஆங்கிலத்தில் இருக்கும்.',
        addPostalSetupTitle: 'அமைப்பை முடிக்க உங்கள் அஞ்சல் குறியீட்டைச் சேர்க்கவும்',
